function heading(title,subtitle,action=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;}
function notice(text,warm=false){return `<div class="notice${warm?' warm':''}">${icon('info')}<div>${text}</div></div>`;}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,4200);}
async function apiJSON(url,options={}){const response=await fetch(url,{...options,headers:{'Content-Type':'application/json',...options.headers},signal:AbortSignal.timeout(10000)});const data=await response.json();if(!response.ok){if(response.status===401&&url!=='/api/session')lockPlatform('Sua sessão expirou. Entre novamente para continuar.');throw new Error(data.message||'Não foi possível concluir a solicitação.');}return data;}
function updateAuthView(){
 const authenticated=authState.checked&&authState.authenticated;
 document.body.classList.toggle('auth-only',!authenticated);
 document.querySelector('#login-screen').hidden=authenticated;
 document.querySelector('#sidebar').hidden=!authenticated;
 document.querySelector('.shell').hidden=!authenticated;
 document.querySelector('.skip-link').href=authenticated?'#main':'#login-content';
 const form=document.querySelector('#login-form'),status=document.querySelector('#session-status');
 form.hidden=authenticated||!authState.available||!authState.accessConfigured;
 status.textContent=authState.message||(!authState.checked?'Verificando acesso ao servidor…':!authState.available?'Não foi possível conectar ao servidor. Inicie a YENA com npm.cmd start.':!authState.accessConfigured?'O acesso administrativo precisa ser configurado no servidor.':'');
 status.hidden=!status.textContent;
 document.querySelector('#session-retry').hidden=authenticated||!['http:','https:'].includes(location.protocol)||(!status.textContent&&authState.available);
 document.querySelector('#open-local-app').hidden=authenticated||location.protocol!=='file:';
 if(!authenticated){document.title='Entrar · YENA Healthcare Technology';closeMenu();main.replaceChildren();}
}
function lockPlatform(message=''){
 authVersion++;cancelChat();if(dialog.open)dialog.close();
 authState={...authState,checked:true,authenticated:false,message};
 dataConnection={...dataConnection,authenticated:false,user:null};
 clients=[];savedQuotes=[];quoteClientId='';messages=[{role:'assistant',text:demoGreeting}];reviewed=new Set();
 document.querySelector('#login-password').value='';document.querySelector('#login-password').type='password';document.querySelector('.password-toggle').setAttribute('aria-pressed','false');document.querySelector('.password-toggle').setAttribute('aria-label','Mostrar senha');
 updateAccount();updateAuthView();
}
async function refreshSession(hydrate=true){
 if(!['http:','https:'].includes(location.protocol)){authState={...authState,checked:true,available:false,message:'O login funciona pela aplicação com servidor. Execute npm.cmd start e abra o endereço local.'};updateAuthView();return false;}
 const version=authVersion;
 try{
  const session=await apiJSON('/api/session');if(version!==authVersion)return false;
  authState={checked:true,authenticated:session.authenticated===true,available:true,accessConfigured:session.accessConfigured===true,message:''};
  dataConnection={...dataConnection,authenticated:authState.authenticated,user:session.user,accessConfigured:authState.accessConfigured};
  if(!authState.authenticated){lockPlatform();return false;}
  updateAuthView();
  if(hydrate){clients=seedClients();render();await Promise.all([discoverData(),discoverAI()]);}
  return authState.authenticated;
 }catch{if(version===authVersion){authState.available=false;lockPlatform('Não foi possível conectar ao servidor. Verifique se a YENA está em execução.');}return false;}
}
function canSave(){return dataConnection.configured&&dataConnection.ready&&dataConnection.authenticated;}
function storageNotice(){
 if(!dataConnection.configured)return notice('<strong>Demonstração sem banco configurado.</strong> Os registros desta página ficam na memória e são perdidos ao recarregar. Para guardar clientes e orçamentos, use o servidor com MySQL configurado.');
 if(!dataConnection.ready)return notice('<strong>MySQL indisponível.</strong> Não foi possível acessar o banco. Verifique o servidor antes de cadastrar ou salvar registros.',true);
 if(!dataConnection.authenticated)return notice('<strong>Armazenamento MySQL disponível.</strong> Entre com o acesso administrativo para consultar e salvar seus registros. <button class="text-link" data-action="login">Entrar na plataforma</button>');
 return notice('<strong>Dados persistentes no MySQL.</strong> Clientes e orçamentos são gravados no servidor após confirmação. Use dados fictícios na apresentação acadêmica.');
}
function updateAccount(){const button=document.querySelector('#account-button');if(!button)return;button.hidden=!dataConnection.accessConfigured;button.textContent=dataConnection.authenticated?'Sair':'Entrar';button.dataset.action=dataConnection.authenticated?'logout':'login';}
async function discoverData(){
 if(!authState.authenticated)return;
 const version=authVersion;
 try{const status=await apiJSON('/api/data/status');if(version!==authVersion||status.storage!=='mysql')return;dataConnection=status;if(status.configured){clients=[];savedQuotes=[];if(canSave()){const [c,q]=await Promise.all([apiJSON('/api/clients'),apiJSON('/api/quotes')]);if(version!==authVersion)return;clients=c.clients;savedQuotes=q.quotes;}}updateAccount();if(['inicio','clientes','orcamentos','configuracoes'].includes(route)&&!dialog.open)render();}catch{if(version===authVersion&&dataConnection.configured){dataConnection.ready=false;clients=[];savedQuotes=[];if(['clientes','orcamentos'].includes(route)&&!dialog.open)render();}}
}
