function monitoring(){return `${heading('Monitoramento','Ambientes e alertas reunidos em uma visão demonstrativa.')} ${notice('<strong>Monitoramento simulado.</strong> As ilustrações, conexões, horários e alertas são fictícios. Não há câmeras físicas conectadas nem análise de imagens reais.')}
 <div class="filters"><div class="field"><label for="room-filter">Ambiente</label><select id="room-filter"><option value="todos">Todos os ambientes</option>${rooms.map(r=>`<option value="${r.id}"${monitorFilters.room===r.id?' selected':''}>${r.name}</option>`).join('')}</select></div><div class="field"><label for="priority-filter">Prioridade dos alertas</label><select id="priority-filter">${['todas','Alta','Média','Baixa'].map(p=>`<option value="${p}"${monitorFilters.priority===p?' selected':''}>${p==='todas'?'Todas as prioridades':p}</option>`).join('')}</select></div><button class="button secondary" data-action="clear-monitor">Limpar filtros</button></div>
 <section aria-label="Câmeras demonstrativas" class="camera-grid" id="camera-grid">${cameraCards()}</section><div class="section-heading"><div><h2>Central de alertas</h2><p>Horários ilustrativos · alterações válidas apenas nesta sessão</p></div><span id="alert-count" class="muted" style="font-size:10px"></span></div><section class="panel" id="alerts-table" aria-label="Alertas simulados">${alertTable()}</section>`;}
function filteredAlerts(){return alerts.filter(a=>(monitorFilters.room==='todos'||a.room===monitorFilters.room)&&(monitorFilters.priority==='todas'||a.priority===monitorFilters.priority));}
function cameraCards(){return rooms.filter(r=>monitorFilters.room==='todos'||r.id===monitorFilters.room).map(r=>`<article class="camera-card"><div class="camera-visual">${roomArt(rooms.indexOf(r))}<span class="camera-overlay">ILUSTRAÇÃO · SIMULAÇÃO</span>${!r.online?`<div class="offline-message">${icon('offline')}Sinal indisponível na simulação</div>`:''}</div><div class="camera-bottom"><div><h3>${r.name}</h3><p>${r.code} · Ambiente fictício</p></div><span class="status${r.online?'':' offline'}"><span class="status-dot${r.online?'':' offline'}"></span>${r.online?'Conectada':'Desconectada'} (simulação)</span></div></article>`).join('');}
function alertTable(){const list=filteredAlerts();return list.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Evento demonstrativo</th><th>Ambiente</th><th>Horário fictício</th><th>Prioridade</th><th>Revisão</th><th><span class="sr-only">Ações</span></th></tr></thead><tbody>${list.map(a=>`<tr><td><strong>${a.title}</strong><small>Evento simulado</small></td><td>${roomName(a.room)}</td><td>${a.time}</td><td><span class="priority ${priorityClass(a.priority)}">${a.priority}</span></td><td>${reviewed.has(a.id)?'<span class="reviewed">Revisado</span>':'Pendente'}</td><td><button class="text-link" data-action="alert-detail" data-id="${a.id}">Ver detalhes ${icon('chevron')}</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nenhum alerta corresponde aos filtros selecionados.</div>';}
function updateMonitor(){document.querySelector('#camera-grid').innerHTML=cameraCards();document.querySelector('#alerts-table').innerHTML=alertTable();document.querySelector('#alert-count').textContent=`${filteredAlerts().length} alerta(s)`;}
function customers(){return `${heading('Clientes','Organize os contatos e as necessidades de cada instituição.',`<button class="button" data-action="client-new"${dataConnection.configured&&!canSave()?' disabled':''}>${icon('plus')} Novo cliente</button>`)}${storageNotice()}
 <div class="filters"><div class="field search-field"><label class="sr-only" for="client-search">Buscar cliente, instituição ou contato</label><div class="search-wrap">${icon('search')}<input class="search-input" id="client-search" type="search" placeholder="Buscar nome, instituição ou contato..." value="${esc(clientFilters.search)}" maxlength="120"></div></div><div class="field"><label class="sr-only" for="client-stage">Filtrar por etapa</label><select id="client-stage">${['todas','Novo contato','Em análise','Orçamento enviado'].map(s=>`<option${clientFilters.stage===s?' selected':''} value="${s}">${s==='todas'?'Todas as etapas':s}</option>`).join('')}</select></div></div><section class="panel" id="clients-table" aria-label="Lista de clientes">${clientTable()}</section>`;}
function filteredClients(){const t=normalize(clientFilters.search);return clients.filter(c=>(clientFilters.stage==='todas'||c.stage===clientFilters.stage)&&normalize(`${c.name} ${c.institution} ${c.contact}`).includes(t));}
function clientTable(){const list=filteredClients();return `${list.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Cliente</th><th>Instituição</th><th>Etapa</th><th>Ações</th></tr></thead><tbody>${list.map(c=>`<tr><td><div class="client-name"><span class="client-avatar">${esc(c.name.split(' ').map(n=>n[0]).slice(0,2).join(''))}</span><div><strong>${esc(c.name)}</strong><small>${esc(c.contact)}</small></div></div></td><td>${esc(c.institution)}</td><td><span class="priority ${c.stage==='Novo contato'?'baixa':c.stage==='Orçamento enviado'?'':'baixa'}">${esc(c.stage)}</span></td><td><div class="actions"><button class="icon-button" data-action="client-view" data-id="${c.id}" aria-label="Visualizar ${esc(c.name)}">${icon('eye')}</button><button class="icon-button" data-action="client-edit" data-id="${c.id}" aria-label="Editar ${esc(c.name)}">${icon('edit')}</button><button class="icon-button" data-action="client-delete" data-id="${c.id}" aria-label="Excluir ${esc(c.name)}">${icon('trash')}</button></div></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${dataConnection.configured&&!dataConnection.authenticated?'Entre para consultar os registros no MySQL.':'Nenhum cliente encontrado.<br>Altere os filtros ou cadastre um contato fictício.'}</div>`}<div class="result-count">${list.length} de ${clients.length} registro(s) · ${dataConnection.configured?'banco MySQL':'demonstração temporária na sessão'}</div>`;}
function quotes(){return `${heading('Orçamentos','Uma estimativa transparente para cada necessidade.')}${notice('<strong>Estimativas acadêmicas.</strong> Os valores de referência fazem parte do TCC e não são preços comerciais definitivos. Nenhum serviço será contratado.',true)}
 <div class="quote-grid"><form id="quote-form" class="panel form-panel"><h2>Monte sua estimativa</h2><p>Selecione o plano, os equipamentos e os serviços.</p><div class="form-section"><fieldset class="plans"><legend>01 · Escolha o plano mensal</legend>${Object.entries(PLANS).map(([id,p])=>`<label class="plan-option"><input type="radio" name="plan" value="${id}"${quoteInput.plan===id?' checked':''} required><span><strong>${p.name}</strong><b>${money(p.price)}</b><small>por mês</small></span></label>`).join('')}</fieldset></div><div class="form-section"><h3>02 · Equipamentos</h3><div class="fields-row"><div class="field"><label for="quote-cameras">Câmeras inteligentes</label><input id="quote-cameras" name="cameras" type="number" min="0" max="10000" step="1" required value="${quoteInput.cameras}"><small>${money(PRICES.camera)} por unidade</small></div><div class="field"><label for="quote-badges">Crachás inteligentes</label><input id="quote-badges" name="badges" type="number" min="0" max="10000" step="1" required value="${quoteInput.badges}"><small>${money(PRICES.badge)} por unidade</small></div></div></div><div class="form-section"><h3>03 · Serviços adicionais</h3><label class="option-row"><input type="checkbox" name="installation"${quoteInput.installation?' checked':''}><span><strong>Instalação</strong><small>Cobrança única no início</small></span><b>${money(PRICES.installation)}</b></label><label class="option-row"><input type="checkbox" name="maintenance"${quoteInput.maintenance?' checked':''}><span><strong>Manutenção</strong><small>Somada à mensalidade do plano</small></span><b>${money(PRICES.maintenance)}/mês</b></label></div><p class="panel-note">${icon('info')} A tabela informa apenas preços de referência, sem diferenças de recursos entre planos.</p></form><aside class="panel quote-summary" id="quote-summary" aria-label="Resumo do orçamento" aria-live="polite">${quoteSummary()}</aside></div>`;}
function quoteSummary(error=''){if(error)return `<div class="summary-head"><h2>Revise os campos</h2></div><div class="summary-body"><p class="error">${esc(error)}</p><p class="muted">Use quantidades inteiras de 0 a 10.000.</p></div>`;const q=calculateQuote(quoteInput);return `<div class="summary-head"><div class="eyebrow">Seu planejamento</div><h2>Resumo da estimativa</h2></div><div class="summary-body"><div class="cost-group"><h3>Investimento inicial · único</h3><div class="cost-line"><span>Câmeras (${q.cameras} × ${money(PRICES.camera)})</span><b>${money(q.cameraCost)}</b></div><div class="cost-line"><span>Crachás (${q.badges} × ${money(PRICES.badge)})</span><b>${money(q.badgeCost)}</b></div><div class="cost-line"><span>Instalação${q.installation?'':' (não incluída)'}</span><b>${money(q.installationCost)}</b></div><div class="cost-total"><span>Total inicial</span><b data-total="initial">${money(q.initial)}</b></div></div><div class="cost-group"><h3>Recorrência mensal</h3><div class="cost-line"><span>Plano ${PLANS[q.plan].name}</span><b>${money(q.planCost)}</b></div><div class="cost-line"><span>Manutenção${q.maintenance?'':' (não incluída)'}</span><b>${money(q.maintenanceCost)}</b></div><div class="cost-total monthly-total"><span>Total mensal</span><b data-total="monthly">${money(q.monthly)}<small>/mês</small></b></div></div><button type="button" class="button" data-action="quote-generate">${icon('document')} Gerar resumo ${icon('arrow')}</button></div><div class="summary-foot">Valores acadêmicos de referência. Equipamentos e instalação são cobrados uma vez; plano e manutenção compõem o custo mensal.</div>`;}
function updateQuote(){const form=document.querySelector('#quote-form'),fd=new FormData(form);const candidate={plan:fd.get('plan'),cameras:fd.get('cameras')===''?NaN:Number(fd.get('cameras')),badges:fd.get('badges')===''?NaN:Number(fd.get('badges')),installation:fd.has('installation'),maintenance:fd.has('maintenance')};try{calculateQuote(candidate);quoteInput=candidate;document.querySelector('#quote-summary').innerHTML=quoteSummary();return true;}catch(e){document.querySelector('#quote-summary').innerHTML=quoteSummary(e.message);return false;}}
function aiModeNotice(){return aiMode==='deepseek'?notice('<strong>Consultas ao DeepSeek pelo servidor.</strong> As mensagens enviadas neste modo seguem para o provedor. Cadastros não são enviados automaticamente; fichas e cálculos continuam locais. Não envie dados pessoais reais ou de saúde.'):notice('<strong>Assistente demonstrativo com regras locais.</strong> Nenhuma IA externa é consultada neste modo. Para usar o DeepSeek, execute o servidor com a credencial configurada.');}
function aiStateLabel(){return aiMode==='deepseek'?'DeepSeek · configurado para consulta':'Regras locais · demonstração';}
function ai(){return `${heading('YENA AI','Informações claras, estimativas e apoio à organização comercial.')}<div id="ai-mode-notice">${aiModeNotice()}</div><div class="ai-mode-panel"><div class="field"><label for="ai-mode">Modo de conversa</label><select id="ai-mode"><option value="demo"${aiMode==='demo'?' selected':''}>Demonstração · regras locais</option><option value="deepseek"${aiMode==='deepseek'?' selected':''}${aiConnection.configured?'':' disabled'}>DeepSeek · IA pelo servidor</option></select></div><p id="ai-connection-status">${esc(aiConnection.configured?'Credencial configurada no servidor. A primeira consulta verificará o acesso.':aiConnection.available?'Servidor disponível; chave do DeepSeek ainda não configurada.':'Modo local disponível. A integração DeepSeek requer o servidor da YENA.')}</p></div>
 <div class="chat-layout"><section class="panel chat-panel" aria-label="Conversa com o assistente"><div class="chat-header"><span class="ai-avatar">${icon('sparkle')}</span><div><strong>YENA AI</strong><small id="ai-state-label">${aiStateLabel()}</small></div><button class="icon-button" style="margin-left:auto" data-action="chat-clear" aria-label="Limpar conversa">${icon('reset')}</button></div><div class="chat-messages" id="chat-messages" role="log" aria-live="polite" aria-relevant="additions">${messages.map(messageMarkup).join('')}</div><p class="chat-pending" id="chat-pending" role="status"${chatBusy?'':' hidden'}>Consultando o DeepSeek…</p><form class="chat-input-area" id="chat-form"><label class="sr-only" for="chat-input">Sua mensagem para YENA AI</label><div class="chat-input-row"><textarea id="chat-input" name="message" rows="1" placeholder="Pergunte sobre a YENA ou calcule um orçamento..." maxlength="1500" required></textarea><button type="submit" class="button" aria-label="Enviar mensagem">${icon('send')}</button></div><small>Confira a origem indicada em cada resposta. Enter envia; Shift + Enter quebra a linha.</small></form></section>
 <aside class="panel chat-tools"><h3>Por onde começar?</h3><p>Explore as informações do projeto.</p><button class="prompt-button" data-prompt="O que é a YENA e quais são seus serviços?">Conhecer a YENA ${icon('arrow')}</button><button class="prompt-button" data-prompt="Quais são os preços dos planos e equipamentos?">Consultar os preços ${icon('arrow')}</button><button class="prompt-button" data-prompt="Calcule um orçamento Profissional com 4 câmeras, 20 crachás, com instalação e manutenção.">Calcular uma estimativa ${icon('arrow')}</button><button class="prompt-button" data-prompt="Prepare um resumo comercial da YENA.">Preparar resumo comercial ${icon('arrow')}</button><hr><h3>Ficha de potencial cliente</h3><p>Organize apenas as informações já cadastradas na sessão.</p><div class="field"><label for="ai-client">Selecionar cliente</label><select id="ai-client"${clients.length?'':' disabled'}>${clients.length?clients.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join(''):'<option>Nenhum cliente cadastrado</option>'}</select></div><button class="button soft" data-action="client-brief"${clients.length?'':' disabled'}>${icon('document')} Preparar ficha</button><a class="text-link" href="#clientes">Gerenciar clientes ${icon('arrow')}</a></aside></div>`;}
function messageMarkup(m){const source=m.source==='deepseek'?`DeepSeek · ${m.model||aiConnection.model}`:m.source==='error'?'Falha na consulta · sem resposta do modelo':m.source==='info'?'Informação do protótipo':'Regras locais · sem consulta externa';return `<div class="message ${m.role==='user'?'user':''}"><span class="ai-avatar" aria-label="${m.role==='user'?'Você':'YENA AI'}">${m.role==='user'?'V':icon('sparkle')}</span><div class="message-content"><div class="message-body">${esc(m.text)}</div>${m.role==='assistant'?`<small class="message-source">${esc(source)}</small>`:''}</div></div>`;}
function addMessage(role,text,meta={}){const m={role,text,...meta};messages.push(m);const log=document.querySelector('#chat-messages');if(log){log.insertAdjacentHTML('beforeend',messageMarkup(m));log.scrollTop=log.scrollHeight;}}
function updateChatBusy(){const form=document.querySelector('#chat-form');if(form)form.setAttribute('aria-busy',String(chatBusy));document.querySelectorAll('#chat-input,#chat-form button,#ai-mode,[data-prompt],[data-action="chat-clear"],[data-action="client-brief"]').forEach(el=>{el.disabled=chatBusy||(el.dataset.action==='client-brief'&&!clients.length);});const pending=document.querySelector('#chat-pending');if(pending)pending.hidden=!chatBusy;}
function cancelChat(){chatVersion++;chatController?.abort();chatController=null;chatBusy=false;updateChatBusy();}
function updateAIConnectionUI(){
 if(!authState.authenticated)return;
 if(messages.length===1){messages[0]={role:'assistant',source:'info',text:aiMode==='deepseek'?'Olá! Eu sou a YENA AI. O servidor está configurado para consultar o DeepSeek.\n\nAs mensagens enviadas no modo DeepSeek seguem para esse provedor. Fichas de clientes e cálculos de orçamento continuam locais, com a origem indicada em cada resposta. Posso apresentar a empresa, seus serviços propostos e preparar resumos comerciais.\n\nComo posso ajudar?':demoGreeting};}
 if(route==='ai'){const draft=document.querySelector('#chat-input')?.value||'';main.innerHTML=ai();document.querySelector('#chat-input').value=draft;updateChatBusy();}
}
async function discoverAI(){
 if(!authState.authenticated)return;
 try{const response=await fetch('/api/ai/status',{cache:'no-store',signal:AbortSignal.timeout(4000)});if(!response.ok)return;const data=await response.json();if(data.provider!=='deepseek'||typeof data.configured!=='boolean')return;aiConnection={configured:data.configured,model:String(data.model||''),available:true};aiMode=data.configured?'deepseek':'demo';updateAIConnectionUI();}catch{/* Uma página estática continua funcionando no modo local. */}
}
function aiAnswer(input){const t=normalize(input);
 if(/orcamento|estimativa|calcule|calcular/.test(t)){const result=parseQuote(input);return result.error||`${quoteText(result.quote)}\n\nCritérios de leitura: quantidades ausentes = 0; instalação e manutenção só são incluídas quando mencionadas sem negação. Confira os itens acima ou use o formulário de Orçamentos.`;}
 if(/resumo|comercial|apresentacao/.test(t))return 'RESUMO COMERCIAL · DEMONSTRAÇÃO\n\nYENA Healthcare Technology é uma empresa fictícia de um TCC, com o slogan “Cuidando quando não se pode ver”. Sua proposta reúne tecnologia e cuidado humano.\n\nO protótipo oferece monitoramento simulado por ambientes, organização de alertas, um assistente demonstrativo e gestão temporária de contatos e estimativas. Inteligência Artificial e Realidade Aumentada fazem parte da proposta; a RA é um conceito futuro, sem implementação neste protótipo.\n\nPlanos de referência: Básico R$ 1.500,00/mês; Profissional R$ 2.500,00/mês; Premium R$ 4.000,00/mês. Equipamentos, instalação e manutenção são calculados à parte. Valores acadêmicos, sem validade comercial.\n\nPróximo passo sugerido: levantar a necessidade da instituição e preparar uma estimativa no módulo Orçamentos.';
 if(/ficha|potencia[il]|lead|cliente/.test(t))return 'Para preparar uma ficha sem inventar informações, selecione um cliente no painel de apoio e clique em “Preparar ficha”. Você pode cadastrar ou editar contatos fictícios em Clientes. Usarei apenas os campos existentes na sessão.';
 if(/prec|valor|custa|planos|mensal|tabela/.test(t))return `TABELA DE REFERÊNCIA ACADÊMICA\n\n${Object.values(PLANS).map(p=>`Plano ${p.name}: ${money(p.price)}/mês`).join('\n')}\nInstalação: ${money(PRICES.installation)} (única)\nCâmera inteligente: ${money(PRICES.camera)}/unidade\nCrachá inteligente: ${money(PRICES.badge)}/unidade\nManutenção: ${money(PRICES.maintenance)}/mês\n\nCustos iniciais = câmeras + crachás + instalação opcional.\nCustos mensais = plano + manutenção opcional.\n\nOs planos não têm diferenças de funcionalidades especificadas no projeto. Estes valores não são preços comerciais definitivos.`;
 if(/realidade|aumentada|\bra\b/.test(t))return 'A Realidade Aumentada faz parte da visão futura da YENA: apresentar informações digitais no contexto do ambiente físico. Não há recursos de RA, dispositivos reais ou integração com câmeras neste protótipo. Detalhes de implementação ainda não foram definidos.';
 if(/ia|inteligencia|modelo|externa|voce|funciona/.test(t)&&!/empresa|servico/.test(t))return 'Esta YENA AI é uma demonstração com regras locais e respostas pré-definidas, sem consulta a modelos externos. Posso calcular estimativas com a tabela do projeto e organizar informações de clientes cadastrados. Não faço detecção de eventos, análise de imagens, diagnóstico ou atendimento clínico.';
 if(/yena|empresa|servico|missao|visao|valores|diferencia/.test(t))return 'A YENA Healthcare Technology é uma empresa fictícia desenvolvida para um TCC.\n\nSlogan: “Cuidando quando não se pode ver”.\n\nMissão proposta: apoiar o cuidado humano com informações acessíveis e organizadas. Visão: aproximar inovação e atenção às pessoas. Valores: empatia, acessibilidade, transparência, responsabilidade e respeito à privacidade.\n\nA proposta explora monitoramento de ambientes, apoio com Inteligência Artificial e o conceito futuro de Realidade Aumentada. Neste protótipo, o monitoramento é inteiramente simulado, o assistente funciona por regras locais e a RA não está implementada.\n\nOs diferenciais demonstrados são a centralização das informações, a organização de alertas por ambiente e prioridade e a separação clara dos custos nas estimativas.';
 if(/^(oi|ola|bom dia|boa tarde|boa noite|obrigad)/.test(t))return 'Olá! Posso ajudar com informações sobre a YENA, preços acadêmicos, estimativas e fichas de clientes. Para calcular, experimente: “Orçamento Básico com 2 câmeras, 10 crachás, sem instalação e com manutenção”.';
 return 'Não tenho essa informação na base deste projeto. Para evitar inventar dados, posso responder sobre a empresa, os serviços propostos, a tabela de preços acadêmicos, orçamentos e fichas de clientes cadastrados. Use uma das sugestões ao lado ou o formulário de Orçamentos.';
}
async function sendChat(input){
 const text=input.trim();if(!text||chatBusy)return;if(text.length>1500){toast('Use até 1.500 caracteres por mensagem.');return;}
 const local=aiMode!=='deepseek'||/orcamento|estimativa|calcule|calcular|ficha|potencia[il]|lead|cliente/.test(normalize(text));
 if(local){addMessage('user',text,{source:'local'});addMessage('assistant',aiAnswer(text),{source:'local'});return;}
 addMessage('user',text,{source:'deepseek'});chatBusy=true;chatController=new AbortController();const controller=chatController,version=chatVersion;updateChatBusy();
 try{
   let history=messages.filter(m=>m.source==='deepseek').slice(-10).map(m=>({role:m.role,content:m.text}));
   while(history.reduce((n,m)=>n+m.content.length,0)>16000&&history.length>1)history.shift();
   const timeout=setTimeout(()=>controller.abort('timeout'),40000);
   let response,data;
   try{response=await fetch('/api/ai/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({messages:history}),signal:controller.signal});data=await response.json();}finally{clearTimeout(timeout);}
   if(response.status===401){lockPlatform('Sua sessão expirou. Entre novamente para continuar.');return;}
   if(!response.ok)throw new Error(typeof data.message==='string'?data.message:'Não foi possível consultar o DeepSeek.');
   if(data.provider!=='deepseek'||typeof data.text!=='string'||!data.text.trim())throw new Error('O servidor retornou uma resposta inválida.');
   if(version===chatVersion)addMessage('assistant',data.text+(data.truncated?'\n\nA resposta atingiu o limite de tamanho. Peça para continuar, se necessário.':''),{source:'deepseek',model:data.model});
 }catch(error){if(version===chatVersion)addMessage('assistant',controller.signal.aborted?'A consulta foi interrompida ou demorou mais que o esperado. Nenhuma resposta de IA foi recebida.':error instanceof TypeError?'Não foi possível acessar o servidor da YENA. Verifique se ele está em execução.':error.message,{source:'error'});}
 finally{if(version===chatVersion){chatBusy=false;chatController=null;updateChatBusy();}}
}
function settings(){return `${heading('Configurações','Acesso, armazenamento e preferências da plataforma.')}<div class="settings-grid">
 <section class="panel settings-card"><h2>Sobre a YENA</h2><p>Empresa fictícia desenvolvida para um Trabalho de Conclusão de Curso. Cuidando quando não se pode ver.</p><div class="detail-list"><div><span>Versão</span><strong>1.2 · protótipo acadêmico</strong></div><div><span>Interface</span><strong>Português brasileiro</strong></div><div><span>Monitoramento</span><strong>100% simulado</strong></div><div><span>Assistente</span><strong>${aiConnection.configured?'DeepSeek e modo local':'Modo local; DeepSeek não configurado'}</strong></div><div><span>Dispositivos físicos e RA</span><strong>Não integrados</strong></div></div></section>
 <section class="panel settings-card"><h2>Armazenamento e acesso</h2>${storageNotice()}<p>Clientes e orçamentos são persistidos quando o MySQL está disponível e o acesso está autenticado. Conversa, filtros e alertas de exemplo continuam temporários.</p><p style="margin-top:12px">No modo DeepSeek, as mensagens enviadas seguem para o provedor; os cadastros não são enviados automaticamente.</p>${dataConnection.accessConfigured?`<button class="button secondary" data-action="${dataConnection.authenticated?'logout':'login'}">${dataConnection.authenticated?'Encerrar sessão':'Entrar na plataforma'}</button>`:''}</section>
 <section class="panel settings-card"><h2>Acessibilidade</h2><label class="switch-label" for="reduced-motion"><span>Reduzir movimentos da interface</span><input id="reduced-motion" type="checkbox"${reducedMotion?' checked':''}></label><p>A preferência de movimento reduzido do sistema também é respeitada.</p><button class="button secondary" data-action="reset-demo">${icon('reset')} Restaurar exemplos da interface</button></section>
 <section class="panel settings-card"><h2>Identidade visual</h2><p>Identidade adaptada da referência fornecida para o projeto.</p><div class="brand-swatches"><span style="--swatch:#443966">Roxo<small>#443966</small></span><span style="--swatch:#f59e0b">Laranja<small>#f59e0b</small></span><span style="--swatch:#0f172a">Azul-escuro<small>#0f172a</small></span><span style="--swatch:#e2e8f0">Cinza-claro<small>#e2e8f0</small></span></div><p>Mais que tecnologia, é sobre pessoas.</p></section></div>`;}
function quoteHistory(){return `<div class="section-heading"><div><h2>Orçamentos salvos</h2><p>Histórico de estimativas acadêmicas no MySQL</p></div></div>${storageNotice()}<div class="panel">${savedQuotes.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Plano / cliente</th><th>Inicial</th><th>Mensal</th><th>Data</th><th>Ações</th></tr></thead><tbody>${savedQuotes.map(q=>`<tr><td><strong>${esc(PLANS[q.snapshot.plan]?.name||q.snapshot.plan)}</strong><small>${esc(q.clientName||'Sem vínculo com cliente')}</small></td><td>${money(q.snapshot.initial)}</td><td>${money(q.snapshot.monthly)}</td><td>${new Date(q.createdAt).toLocaleDateString('pt-BR')}</td><td><div class="actions"><button class="icon-button" data-action="quote-view" data-id="${q.id}" aria-label="Ver orçamento">${icon('eye')}</button><button class="icon-button" data-action="quote-delete" data-id="${q.id}" aria-label="Excluir orçamento">${icon('trash')}</button></div></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nenhum orçamento salvo para exibir.</div>'}</div>`;}
function render(){if(!authState.authenticated){updateAuthView();return;}updateAuthView();let next=location.hash.slice(1)||'inicio';if(!routes.some(r=>r[0]===next)){history.replaceState(null,'','#inicio');next='inicio';}route=next;const label=routes.find(r=>r[0]===route)[1];document.title=`${label} · YENA Healthcare Technology`;document.querySelector('#crumb').textContent=label;document.querySelectorAll('.nav-link').forEach(a=>{const active=a.dataset.route===route;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 main.innerHTML=({inicio:home,monitoramento:monitoring,clientes:customers,orcamentos:()=>quotes()+'<section id="quote-history">'+quoteHistory()+'</section>',ai,configuracoes:settings}[route])();closeMenu();if(route==='monitoramento')updateMonitor();if(route==='ai')updateChatBusy();window.scrollTo({top:0,behavior:'instant'});}
function closeMenu(){document.querySelector('#sidebar').classList.remove('open');document.querySelector('#scrim').hidden=true;document.querySelector('#menu-toggle').setAttribute('aria-expanded','false');}
function openDialog(title,body,actions='',formId=''){document.querySelector('#dialog-content').innerHTML=`${formId?`<form id="${formId}">`:''}<div class="dialog-header"><h2 id="dialog-title">${title}</h2><button type="button" class="icon-button" data-action="dialog-close" aria-label="Fechar janela">${icon('close')}</button></div><div class="dialog-body">${body}</div>${actions?`<div class="dialog-actions">${actions}</div>`:''}${formId?'</form>':''}`;if(!dialog.open)dialog.showModal();}
const closeButton='<button type="button" class="button secondary" data-action="dialog-close">Fechar</button>';
function clientForm(id){const c=clients.find(c=>c.id===id)||{name:'',institution:'',contact:'',need:'',stage:'Novo contato'};openDialog(id?'Editar cliente':'Novo cliente',`<p style="margin-bottom:17px">Use dados fictícios. ${dataConnection.configured?'O registro será salvo no MySQL após confirmação.':'O registro vale apenas para esta sessão de demonstração.'}</p><input type="hidden" name="id" value="${esc(id||'')}"><div class="field"><label for="client-name">Nome do contato *</label><input id="client-name" name="name" required maxlength="80" value="${esc(c.name)}" placeholder="Ex.: Ana Exemplo" autocomplete="off"></div><div class="field"><label for="client-institution">Instituição *</label><input id="client-institution" name="institution" required maxlength="120" value="${esc(c.institution)}" placeholder="Ex.: Clínica Modelo (fictícia)" autocomplete="off"></div><div class="field"><label for="client-contact">Contato profissional fictício *</label><input id="client-contact" name="contact" required maxlength="120" value="${esc(c.contact)}" placeholder="Ex.: ana@exemplo.invalid" autocomplete="off"><small>Um e-mail ou telefone de exemplo é suficiente.</small></div><div class="field"><label for="client-need">Necessidade *</label><textarea id="client-need" name="need" required maxlength="1000" placeholder="Descreva a necessidade da instituição, sem dados de saúde.">${esc(c.need)}</textarea></div><div class="field"><label for="client-status">Etapa</label><select id="client-status" name="stage">${['Novo contato','Em análise','Orçamento enviado'].map(s=>`<option${s===c.stage?' selected':''}>${s}</option>`).join('')}</select></div><p id="client-error" class="error" role="alert" hidden></p>`,`<button type="button" class="button secondary" data-action="dialog-close">Cancelar</button><button type="submit" class="button">${icon('check')} ${dataConnection.configured?'Salvar no MySQL':'Salvar na sessão'}</button>`,'client-form');}
function alertDetail(id){const a=alerts.find(a=>a.id===id);if(!a)return;openDialog('Detalhes do alerta',`<span class="priority ${priorityClass(a.priority)}">Prioridade ${a.priority.toLowerCase()}</span><h3 style="margin:17px 0 10px">${a.title}</h3><p>${a.description}</p><dl><dt>Ambiente</dt><dd>${roomName(a.room)}</dd><dt>Horário fictício</dt><dd>${a.time} · evento de demonstração</dd><dt>Contexto</dt><dd>${a.context}</dd><dt>Estado da revisão</dt><dd>${reviewed.has(id)?'Revisado nesta sessão':'Pendente de revisão'}</dd></dl>`,`${closeButton}${reviewed.has(id)?'':`<button class="button" data-action="alert-review" data-id="${id}">${icon('check')} Marcar como revisado</button>`}`);}
function download(filename,content){const blob=new Blob([content],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Resumo preparado para download.');}
document.addEventListener('click',async event=>{
 const target=event.target.closest('[data-action],[data-prompt]');if(!target)return;
 if(target.dataset.prompt){if(authState.authenticated)sendChat(target.dataset.prompt);return;}
 const {action,id}=target.dataset;const c=id?clients.find(c=>c.id===id):null;
 if(action==='toggle-password'){const input=document.querySelector('#login-password'),show=input.type==='password';input.type=show?'text':'password';target.setAttribute('aria-pressed',String(show));target.setAttribute('aria-label',show?'Ocultar senha':'Mostrar senha');return;}
 if(action==='session-retry'){target.disabled=true;await refreshSession();target.disabled=false;return;}
 if(action==='login'){loginDialog();return;}
 if(!authState.authenticated)return;
 if(action==='logout'){target.disabled=true;try{await apiJSON('/api/session',{method:'DELETE'});history.replaceState(null,'','#inicio');lockPlatform('Sessão encerrada. Entre para acessar a plataforma.');document.querySelector('#login-user').focus();}catch{target.disabled=false;toast('Não foi possível encerrar a sessão. Tente novamente.');}return;}
 if(action==='dialog-close'){dialog.close();return;}
 if(action==='clear-monitor'){monitorFilters={room:'todos',priority:'todas'};render();}
 if(action==='alert-detail')alertDetail(id);
 if(action==='alert-review'){reviewed.add(id);dialog.close();updateMonitor();toast('A revisão foi registrada nesta sessão.');}
 if(action==='client-new')clientForm();
 if(action==='client-edit'&&c)clientForm(id);
 if(action==='client-view'&&c)openDialog('Ficha do cliente',`<dl><dt>Nome</dt><dd>${esc(c.name)}</dd><dt>Instituição</dt><dd>${esc(c.institution)}</dd><dt>Contato</dt><dd>${esc(c.contact)}</dd><dt>Necessidade</dt><dd>${esc(c.need)}</dd><dt>Etapa</dt><dd>${esc(c.stage)}</dd></dl><p class="panel-note">${dataConnection.configured?'Registro persistente no MySQL':'Registro temporário na demonstração'}</p>`,`${closeButton}<button class="button" data-action="client-edit" data-id="${id}">${icon('edit')} Editar</button>`);
 if(action==='client-delete'&&c)openDialog('Excluir registro?',`<p>O registro de <strong>${esc(c.name)}</strong>, da instituição ${esc(c.institution)}, será removido ${dataConnection.configured?'do MySQL':'da sessão atual'}.</p>`,`<button class="button secondary" data-action="dialog-close">Cancelar</button><button class="button danger" data-action="client-confirm-delete" data-id="${id}">Excluir registro</button>`);
 if(action==='client-confirm-delete'&&c){target.disabled=true;try{if(dataConnection.configured)await apiJSON('/api/clients/'+id,{method:'DELETE'});clients=clients.filter(x=>x.id!==id);savedQuotes=savedQuotes.map(q=>q.clientId===id?{...q,clientId:null,clientName:null}:q);dialog.close();document.querySelector('#clients-table').innerHTML=clientTable();toast(dataConnection.configured?'Cliente excluído do MySQL.':'Registro excluído da sessão.');}catch(error){toast(error.message);target.disabled=false;}}
 if(action==='quote-generate'){if(!updateQuote())return;const q=calculateQuote(quoteInput);const association=canSave()?`<div class="field"><label for="summary-client">Vincular a um cliente (opcional)</label><select id="summary-client"><option value="">Sem vínculo</option>${clients.map(c=>`<option value="${c.id}">${esc(c.name)} · ${esc(c.institution)}</option>`).join('')}</select></div>`:storageNotice();openDialog('Resumo do orçamento',`<pre>${esc(quoteText(q))}</pre>${association}`,`${closeButton}<button class="button secondary" data-action="quote-download">${icon('download')} Baixar .txt</button>${canSave()?'<button class="button" data-action="quote-save">Salvar no MySQL</button>':''}`);}
 if(action==='quote-save'){if(!canSave())return;target.disabled=true;try{const {quote}=await apiJSON('/api/quotes',{method:'POST',body:JSON.stringify({...quoteInput,clientId:document.querySelector('#summary-client')?.value||null})});savedQuotes.unshift({...quote,clientName:clients.find(c=>c.id===quote.clientId)?.name||null,createdAt:new Date().toISOString()});document.querySelector('#quote-history').innerHTML=quoteHistory();target.textContent='Salvo no MySQL';toast('Orçamento salvo no MySQL.');}catch(error){target.disabled=false;toast(error.message);}}
 if(action==='quote-view'){const q=savedQuotes.find(q=>q.id===id);if(q)openDialog('Orçamento salvo no MySQL',`<pre>${esc(quoteText(q.snapshot))}</pre>`,closeButton);}
 if(action==='quote-delete')openDialog('Excluir orçamento?',`<p>O orçamento selecionado será removido do MySQL.</p>`,`<button class="button secondary" data-action="dialog-close">Cancelar</button><button class="button danger" data-action="quote-confirm-delete" data-id="${id}">Excluir orçamento</button>`);
 if(action==='quote-confirm-delete'){target.disabled=true;try{await apiJSON('/api/quotes/'+id,{method:'DELETE'});savedQuotes=savedQuotes.filter(q=>q.id!==id);dialog.close();document.querySelector('#quote-history').innerHTML=quoteHistory();toast('Orçamento excluído do MySQL.');}catch(error){target.disabled=false;toast(error.message);}}
 if(action==='quote-download'){try{download('YENA-estimativa-academica.txt',quoteText(calculateQuote(quoteInput)));}catch(e){toast(e.message);}}
 if(action==='chat-clear'){openDialog('Limpar conversa?',`<p>As mensagens serão removidas da sessão. A mensagem de apresentação será mantida.</p>`,`<button class="button secondary" data-action="dialog-close">Cancelar</button><button class="button" data-action="chat-confirm-clear">Limpar conversa</button>`);}
 if(action==='chat-confirm-clear'){cancelChat();messages=messages.slice(0,1);dialog.close();render();toast('Conversa limpa.');}
 if(action==='client-brief'){const selected=clients.find(c=>c.id===document.querySelector('#ai-client').value);if(!selected)return;addMessage('user',`Prepare a ficha de ${selected.name}.`);addMessage('assistant',`FICHA DE POTENCIAL CLIENTE · DEMONSTRAÇÃO\n\nNome: ${selected.name}\nInstituição: ${selected.institution}\nContato: ${selected.contact}\nNecessidade informada: ${selected.need}\nEtapa registrada: ${selected.stage}\n\nPlano de interesse: não definido em um campo específico.\nOrçamento disponível: não informado.\n\nPróximo passo sugerido: confirmar os requisitos com a instituição e montar uma estimativa acadêmica.\n\nFicha organizada apenas com os campos do cadastro atual. Nenhuma informação externa foi consultada.`);}
 if(action==='reset-demo')openDialog('Restaurar demonstração?',`<p>As preferências, a conversa e as revisões voltarão aos exemplos iniciais. ${dataConnection.configured?'Clientes e orçamentos do MySQL serão preservados.':'Os clientes temporários também voltarão aos exemplos.'}</p>`,`<button class="button secondary" data-action="dialog-close">Cancelar</button><button class="button" data-action="confirm-reset">Restaurar exemplos</button>`);
 if(action==='confirm-reset'){cancelChat();if(!dataConnection.configured)clients=seedClients();reviewed=new Set();messages=messages.slice(0,1);monitorFilters={room:'todos',priority:'todas'};clientFilters={search:'',stage:'todas'};quoteInput={plan:'profissional',cameras:4,badges:20,installation:true,maintenance:true};reducedMotion=false;document.body.classList.remove('no-motion');dialog.close();render();toast('Exemplos e preferências restaurados.');}
});
document.addEventListener('input',event=>{
 if(event.target.closest('#quote-form'))updateQuote();
 if(event.target.id==='client-search'){clientFilters.search=event.target.value;document.querySelector('#clients-table').innerHTML=clientTable();}
});
document.addEventListener('change',event=>{
 if(event.target.id==='ai-mode'){cancelChat();aiMode=event.target.value==='deepseek'&&aiConnection.configured?'deepseek':'demo';messages=[messages[0]];updateAIConnectionUI();toast(aiMode==='deepseek'?'Modo DeepSeek selecionado. As próximas mensagens serão enviadas ao provedor.':'Modo demonstração selecionado. Respostas por regras locais.');}
 if(event.target.id==='room-filter'){monitorFilters.room=event.target.value;updateMonitor();}
 if(event.target.id==='priority-filter'){monitorFilters.priority=event.target.value;updateMonitor();}
 if(event.target.id==='client-stage'){clientFilters.stage=event.target.value;document.querySelector('#clients-table').innerHTML=clientTable();}
 if(event.target.id==='reduced-motion'){reducedMotion=event.target.checked;document.body.classList.toggle('no-motion',reducedMotion);toast('Preferência atualizada para esta sessão.');}
});
document.addEventListener('submit',async event=>{
 if(event.target.getAttribute('id')==='login-form'){event.preventDefault();const form=event.target,button=form.querySelector('[type="submit"]');if(button.disabled)return;button.disabled=true;button.textContent='Entrando…';const payload={username:form.elements.username.value.trim(),password:form.elements.password.value};form.elements.password.value='';document.querySelector('#login-error').hidden=true;try{await apiJSON('/api/session',{method:'POST',body:JSON.stringify(payload)});payload.password='';if(!await refreshSession())throw new Error('Não foi possível manter sua sessão. Verifique se os cookies estão habilitados.');render();main.focus({preventScroll:true});toast('Acesso autenticado.');}catch(error){payload.password='';const el=document.querySelector('#login-error');el.textContent=error.message;el.hidden=false;document.querySelector('#login-password').focus();}finally{button.disabled=false;button.innerHTML='Entrar na plataforma <span aria-hidden="true">→</span>';}return;}
 if(!authState.authenticated){event.preventDefault();return;}
 if(event.target.getAttribute('id')==='quote-form'){event.preventDefault();return;}
 if(event.target.getAttribute('id')==='client-form'){event.preventDefault();const form=event.target,button=form.querySelector('[type="submit"]');if(button.disabled)return;button.disabled=true;const fd=new FormData(form);try{let data=validateClient(Object.fromEntries(fd));if(dataConnection.configured){const response=await apiJSON('/api/clients'+(data.id?'/'+data.id:''),{method:data.id?'PUT':'POST',body:JSON.stringify(data)});data=response.client;}if(data.id&&clients.some(c=>c.id===data.id)){clients[clients.findIndex(c=>c.id===data.id)]=data;}else{data.id=data.id||crypto.randomUUID();clients.push(data);}dialog.close();document.querySelector('#clients-table').innerHTML=clientTable();toast(dataConnection.configured?'Cliente salvo no MySQL.':'Cliente salvo apenas nesta sessão.');}catch(e){const error=document.querySelector('#client-error');if(error){error.hidden=false;error.textContent=e.message;}button.disabled=false;}}
 if(event.target.getAttribute('id')==='chat-form'){event.preventDefault();const input=document.querySelector('#chat-input');sendChat(input.value);input.value='';input.focus();}
});
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeMenu();if(event.target.id==='chat-input'&&event.key==='Enter'&&!event.shiftKey){event.preventDefault();document.querySelector('#chat-form').requestSubmit();}});
document.querySelector('#menu-toggle').addEventListener('click',()=>{const open=document.querySelector('#sidebar').classList.toggle('open');document.querySelector('#scrim').hidden=!open;document.querySelector('#menu-toggle').setAttribute('aria-expanded',String(open));if(open)document.querySelector('.nav-link.active').focus();});
document.querySelector('#scrim').addEventListener('click',closeMenu);
window.addEventListener('hashchange',()=>{if(dialog.open)dialog.close();render();if(authState.authenticated)main.focus({preventScroll:true});});
window.addEventListener('focus',()=>{if(authState.authenticated)refreshSession(false);});
window.addEventListener('pageshow',event=>{if(event.persisted)refreshSession(false);});
render();
refreshSession();
